// Build Windows ICO and web favicon from the shared BATEO brand SVG.
// Android and PWA PNGs are generated by @capacitor/assets and gen-pwa-icons.
const { app, BrowserWindow } = require("electron");
const fs = require("node:fs");
const path = require("node:path");

const ROOT = path.join(__dirname, "..");
const svgPath = path.join(ROOT, "assets", "bateo-icon.svg");
const svg = fs.readFileSync(svgPath, "utf8")
  .replace(/<metadata>[\s\S]*?<\/metadata>/g, "")
  .replace(/\s+xmlns:c2pa="[^"]*"/g, "");

app.whenReady().then(async () => {
  let win;
  try {
    fs.writeFileSync(path.join(ROOT, "public", "favicon.svg"), svg);
    win = new BrowserWindow({
      show: false,
      width: 256,
      height: 256,
      transparent: true,
      backgroundColor: "#00000000",
      webPreferences: { paintWhenInitiallyHidden: true },
    });
    const html = `<!doctype html><html><head><meta charset="utf-8"><style>
      html,body{margin:0;width:256px;height:256px;overflow:hidden;background:transparent}
      svg{width:256px;height:256px;display:block}
    </style></head><body>${svg}</body></html>`;
    await win.loadURL("data:text/html;charset=utf-8," + encodeURIComponent(html));
    await new Promise((resolve) => setTimeout(resolve, 500));
    const png = (await win.webContents.capturePage()).toPNG();

    // ICO image resource with PNG payload (supported by modern Windows).
    const header = Buffer.alloc(22);
    header.writeUInt16LE(0, 0); // reserved
    header.writeUInt16LE(1, 2); // icon type
    header.writeUInt16LE(1, 4); // image count
    header.writeUInt8(0, 6); // 256 px
    header.writeUInt8(0, 7); // 256 px
    header.writeUInt8(0, 8); // palette
    header.writeUInt8(0, 9); // reserved
    header.writeUInt16LE(1, 10); // color planes
    header.writeUInt16LE(32, 12); // bit depth
    header.writeUInt32LE(png.length, 14);
    header.writeUInt32LE(22, 18); // image data offset
    fs.writeFileSync(path.join(ROOT, "assets", "bateo-icon.ico"), Buffer.concat([header, png]));
    console.log("BATEO brand icons generated");
  } catch (error) {
    console.error("Brand icon generation failed:", error);
    process.exitCode = 1;
  } finally {
    win?.destroy();
    app.quit();
  }
});
